package keycredentiallink

import (
	"bytes"
	"encoding/hex"
	"testing"
	"time"
)

// dsInternalsAzureADUserKey is the Azure AD-sourced Windows Hello key from
// DSInternals' KeyCredential_Parse_UserKey2 test (KeyCredentialTester.cs). Its
// timestamp entry holds the DateTime.ToBinary value 0x48d52ab3b3ba9d7a
// (DateTimeKind.Utc, 636462449645657466 ticks since 0001-01-01).
const dsInternalsAzureADUserKey = ""

// TestAzureADKeyTimestampIsDotNetBinary decodes a real Azure AD key, whose
// timestamps are DateTime.ToBinary values rather than FILETIMEs, and checks the
// creation time comes out as 2017-11-13 instead of a date in year 18231.
func TestAzureADKeyTimestampIsDotNetBinary(t *testing.T) {
	raw, err := hex.DecodeString(dsInternalsAzureADUserKey)
	if err != nil {
		t.Fatal(err)
	}
	kc := &KeyCredentialLink{}
	if _, err := kc.Unmarshal(raw); err != nil {
		t.Fatalf("Unmarshal: %v", err)
	}
	if kc.CreationTime == nil {
		t.Fatal("no creation time decoded")
	}
	want := time.Date(2017, 11, 13, 16, 29, 24, 565746600, time.UTC)
	if got := kc.CreationTime.GetTime(); !got.Equal(want) {
		t.Errorf("CreationTime = %s, want %s", got, want)
	}
}

// dsInternalsAzureADUserKey3 is DSInternals' KeyCredential_Parse_UserKey3 blob, an
// Azure AD key whose entries all round-trip, so its KeyHash checks.
const dsInternalsAzureADUserKey3 = ""

// TestAzureADKeyRoundTripsAndKeepsIntegrity checks a parsed Azure AD key still
// passes CheckIntegrity and marshals back to the same bytes: its timestamps are
// DateTime.ToBinary values, and writing them as FILETIMEs would change the
// entries the KeyHash covers.
func TestAzureADKeyRoundTripsAndKeepsIntegrity(t *testing.T) {
	raw, err := hex.DecodeString(dsInternalsAzureADUserKey3)
	if err != nil {
		t.Fatal(err)
	}
	kc := &KeyCredentialLink{}
	if _, err := kc.Unmarshal(raw); err != nil {
		t.Fatalf("Unmarshal: %v", err)
	}
	if !kc.CheckIntegrity() {
		t.Error("CheckIntegrity failed on a genuine Azure AD key")
	}
	out, err := kc.Marshal()
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(out, raw) {
		t.Errorf("Marshal changed the blob:\n got  %x\n want %x", out, raw)
	}
}
